	je [SCREEN_NUM], 0x00, TANK_HERO_67_5F_DISPATCH_CASE_00
	je [SCREEN_NUM], 0x02, TANK_HERO_67_5F_DISPATCH_CASE_02
	jl [0x5F], 0x00, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [SCREEN_NUM], 0x05, TANK_HERO_67_5F_DISPATCH_CASE_05
	jl [0x5F], 0x04, TANK_PANEL_CURSOR_RESTORE_PREV_CELL

