	je [0x5F], 0x1E, TANK_PANEL_CURSOR_RIGHT_COLUMN_BOTTOM_CLAMP
	jg [0x5F], 0x1E, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x20, TANK_PANEL_CURSOR_BOTTOM_ROW_CLAMP
