	je [0x5F], 0x17, TANK_APPLY_LEFT_RIGHT_INPUT_TO_TURRET
	je [0x5F], 0x00, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x02, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x03, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x04, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x05, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x06, TANK_PANEL_CURSOR_RESTORE_PREV_CELL
	je [0x5F], 0x07, TANK_APPLY_LEFT_RIGHT_INPUT_TO_TURRET
	je [0x5F], 0x0A, TANK_APPLY_BOTH_AXES_INPUT_TO_TURRET
	je [0x5F], 0x0D, TANK_PANEL_CURSOR_SKIP_HOLE_FROM_BELOW
