; Standard frame-render tick loop: blit + selectPage FF +
; copy 0→FF + break, jmp self. Twin of INTRO's FRAME_RENDER_-
; TICK_LOOP (c5a0f57); each level has its own framework loop.
TANK_FRAME_RENDER_TICK_LOOP:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	copyVideoPage src=0x00, dst=0xFF
	break
	jmp TANK_FRAME_RENDER_TICK_LOOP

LABEL_201A:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	break
	jmp LABEL_201A

; Variant of the above: blit + selectPage FF + copy 3→FF
; (instead of 0→FF), then sums hash-vars (call SUM_HASH_VARS_-
; TO_VAR_64) to advance the rng before breaking. Used by
; scenes that draw their composite into page 3 first.
TANK_FRAME_RENDER_FROM_PAGE_3_LOOP:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	copyVideoPage src=0x03, dst=0xFF
	call TANK_RANDOM_HASH_ADVANCE
	break
	jmp TANK_FRAME_RENDER_FROM_PAGE_3_LOOP
LABEL_2030:
	db 0x11

; Frame-emit + palette-swap flash effect: blit FF, select
; FF, PAUSE=2, setPalette 0x1F, blit FE, setPalette 0x01,
; blit FE, PAUSE=6, copyVideoPage 3→FF, break. The double-
; blit with different palettes (0x1F then 0x01) produces a
; visible flicker between two color schemes — used for hit
; flashes or alert effects.
TANK_SCREEN_FLASH_PALETTE_1F_TO_01:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	mov [PAUSE_SLICES], 0x0002
	setPalette 0x1F
	blitFramebuffer 0xFE
	setPalette 0x01
	blitFramebuffer 0xFE
	mov [PAUSE_SLICES], 0x0006
	copyVideoPage src=0x03, dst=0xFF
	break
	jmp TANK_FRAME_RENDER_FROM_PAGE_3_LOOP
LABEL_204E:
	db 0x11

TANK_CLEAR_AND_BLIT_PAGES_1_2_FF:
	fill page=0x01, color=0x00
	fill page=0x02, color=0x00
	selectVideoPage 0x01
	blitFramebuffer 0x01
	blitFramebuffer 0xFF
	blitFramebuffer 0x02
	ret


TANK_CLEAR_PAGES_1_2_AND_BLIT_L0:
